import json


class Record:
    def __init__(self, name, value, tags):
        self.name = name
        self.value = value
        self.tags = tags

    def to_dict(self):
        return {"name": self.name, "value": self.value, "tags": list(self.tags)}

    def to_json(self):
        return json.dumps(self.to_dict(), sort_keys=True)
